sp_widget.client_script:
function ScratchPadController($scope, $location) {
    var c = this;
    c.done = done;
    c.clear = clear;

    function done() {
        var signature = c.accept();
        if (signature.isEmpty) {
            $scope.page.g_form.setValue("inc_emp_signature", "");
        } else {
            $scope.page.g_form.setValue("inc_emp_signature", signature.dataUrl);

        }

    }

    function clear() {
        $scope.page.g_form.setValue("inc_emp_signature", "");

    }

}

sp_widget.css:
.signature-main-div {
  margin: 10px;
  margin-top: 40px;
  border-radius: 6px;
  .signature {
    margin-left: auto;
    margin-right: auto;
    margin-bottom: 10px;
  }
  .signature canvas {
    border: 1px solid #ddd;
    border-radius: 6px;
    margin: 0 auto;
    cursor: pointer;
  }
}
